const $=id=>document.getElementById(id),lords=['Ketu','Venus','Sun','Moon','Mars','Rahu','Jupiter','Saturn','Mercury'],years=[7,20,6,10,7,18,16,19,17],Y=365.25636*86400000,nak=['Ashwini','Bharani','Krittika','Rohini','Mrigashira','Ardra','Punarvasu','Pushya','Ashlesha','Magha','Purva Phalguni','Uttara Phalguni','Hasta','Chitra','Swati','Vishakha','Anuradha','Jyeshtha','Mula','Purva Ashadha','Uttara Ashadha','Shravana','Dhanishta','Shatabhisha','Purva Bhadrapada','Uttara Bhadrapada','Revati'],signs=['Aries','Taurus','Gemini','Cancer','Leo','Virgo','Libra','Scorpio','Sagittarius','Capricorn','Aquarius','Pisces'];
const themes={Ketu:['reflection and release','Make space to reflect, simplify commitments, and reconnect with what feels meaningful.'],Venus:['connection and creativity','Give attention to relationships, creative work, and the pleasures that restore you.'],Sun:['identity and responsibility','Clarify your priorities and practice taking ownership without seeking constant recognition.'],Moon:['care and emotional rhythm','Notice emotional patterns, make room for rest, and nurture the people and places that support you.'],Mars:['initiative and steady effort','Channel energy into one clear goal and pause before reacting to friction.'],Rahu:['exploration and discernment','Explore unfamiliar opportunities while checking assumptions and avoiding impulsive commitments.'],Jupiter:['learning and perspective','Seek a mentor, deepen a skill, or revisit the principles guiding your decisions.'],Saturn:['structure and patience','Build a sustainable routine and give long-term commitments realistic time to develop.'],Mercury:['communication and learning','Make space for writing, useful conversations, and careful review of details.']};
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function fmt(t){return new Date(t).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'})}function parts(t,z){let p=new Intl.DateTimeFormat('en-GB',{timeZone:z,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(t));let o=Object.fromEntries(p.map(v=>[v.type,v.value]));return Date.UTC(+o.year,+o.month-1,+o.day,+o.hour,+o.minute,+o.second)}
function utc(date,time,z,offset){let wall=Date.parse(date+'T'+time+'Z');if(offset!=='')return wall-Number(offset)*3600000;let candidates=[];for(let h=-36;h<=36;h+=6){let probe=wall+h*3600000;let candidate=wall-(parts(probe,z)-probe);if(parts(candidate,z)===wall&&!candidates.includes(candidate))candidates.push(candidate)}if(candidates.length!==1)throw Error(candidates.length?'This birth time occurs twice during daylight-saving change. Enter its UTC offset.':'This clock time does not exist in that time zone. Check the time or enter the known UTC offset.');return candidates[0]}
function subdiv(p){let a=[],t=p.start;for(let k=0;k<9;k++){let i=(p.i+k)%9,end=k===8?p.end:t+(p.end-p.start)*years[i]/120;a.push({i,start:t,end});t=end}return a}
function calc(birth){let tropical=Astronomy.EclipticGeoMoon(new Date(birth)).lon;let ay=23.8531+50.29/3600*((birth-Date.UTC(2000,0,1,12))/Y);let moon=(tropical-ay+360)%360,n=Math.floor(moon/(40/3)),i=n%9,f=moon/(40/3)-n,t=birth-f*years[i]*Y,periods=[];for(let k=0;k<19;k++){let j=(i+k)%9,end=t+years[j]*Y;periods.push({i:j,start:t,end});t=end}return {moon,n,ay,periods,balance:(1-f)*years[i]}}
function at(periods,t){return periods.find(p=>t>=p.start&&t<p.end)}function tree(p,depth,birth,now){if(p.end<=birth)return '';let active=now>=p.start&&now<p.end;return `<details ${active?'open':''}><summary><span>${lords[p.i]} ${active?'<b class="now"> · ACTIVE</b>':''}</span><small>${fmt(Math.max(p.start,birth))} – ${fmt(p.end)}</small></summary><p class="period-note">${themes[lords[p.i]][1]} ${p.start<birth?'This period began before birth; the dates above show the remaining balance.':''}</p>${depth<2?subdiv(p).map(s=>tree(s,depth+1,birth,now)).join(''):''}</details>`}
let report='';$('date').max=new Date().toISOString().slice(0,10);const cityCoordinates=[[19.076,72.8777],[28.6139,77.209],[12.9716,77.5946],[40.7128,-74.006],[41.8781,-87.6298],[34.0522,-118.2437],[51.5074,-.1278],[-33.8688,151.2093],[25.2048,55.2708],[13.0827,80.2707]];$('city').onchange=()=>{$('custom').hidden=$('city').value!=='custom';let coords=cityCoordinates[$('city').selectedIndex]||['',''];$('latitude').value=coords[0];$('longitude').value=coords[1]};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b))});$('dashas').hidden=b.dataset.tab!=='dashas';$('month').hidden=b.dataset.tab!=='month'});
$('form').onsubmit=e=>{e.preventDefault();$('error').textContent='';try{let z=$('city').value==='custom'?$('zone').value.trim():$('city').value;if(!z)throw Error('Enter the IANA time zone for your birthplace.');if($('city').value==='custom'&&!$('place').value.trim())throw Error('Enter your birth location.');let birth=utc($('date').value,$('time').value,z,$('offset').value),now=Date.now();if(!Number.isFinite(birth)||birth>now||birth<Date.UTC(1900,0,1))throw Error('Choose a valid birth date between 1900 and today.');let lat=$('latitude').value,lon=$('longitude').value;if((lat==='')!==(lon===''))throw Error('Enter both coordinates or leave both blank for a Moon chart.');let r=calc(birth),detail={name:$('name').value.trim(),localDate:$('date').value,localTime:$('time').value,zone:z,place:$('city').value==='custom'?$('place').value:$('city').selectedOptions[0].text,birth,moon:r.moon,ayanamsa:r.ay,periods:r.periods,latitude:lat===''?null:Number(lat),longitude:lon===''?null:Number(lon)};try{if($('remember').checked)localStorage.setItem('jyothish-birth-profile',JSON.stringify(Object.fromEntries(['name','date','time','place','zone','offset','latitude','longitude'].map(id=>[id,$(id).value]).concat([['cityIndex',$('city').selectedIndex]]))));}catch{}window.latestBirthChart=detail;window.dispatchEvent(new CustomEvent('birth-chart',{detail}));let m=at(r.periods,now),a=at(subdiv(m),now),p=at(subdiv(a),now);$('empty').hidden=true;$('results').hidden=false;$('title').textContent=$('name').value.trim()?`${$('name').value.trim()}'s celestial timeline`:'Your celestial timeline';$('mode').textContent='PERSONAL READING';$('stats').innerHTML=`<div class="stat">MOON SIGN<b>${signs[Math.floor(r.moon/30)]}</b>${(r.moon%30).toFixed(3)}° sidereal</div><div class="stat">NAKSHATRA<b>${nak[r.n]}</b>Pada ${Math.floor((r.moon%(40/3))/(10/3))+1}</div><div class="stat">BIRTH BALANCE<b>${r.balance.toFixed(2)} years</b>${lords[r.periods[0].i]} mahadasha</div>`;$('current').innerHTML=`<div class="eyebrow">YOUR CURRENT PERIOD</div><h3>${lords[m.i]} → ${lords[a.i]} → ${lords[p.i]}</h3><p>Mahadasha · Antardasha · Pratyantardasha</p><p>Your current subperiod invites ${themes[lords[p.i]][0]}. ${themes[lords[a.i]][1]}</p><p class="tiny">Pratyantardasha: ${fmt(p.start)} – ${fmt(p.end)} · UTC</p>`;let visible=r.periods.filter(x=>x.start<birth+120*Y);$('timeline').innerHTML=visible.map(x=>tree(x,0,birth,now)).join('');let d=new Date(),start=Date.UTC(d.getFullYear(),d.getMonth()+1,1),end=Date.UTC(d.getFullYear(),d.getMonth()+2,1),t=start,cards=[];while(t<end){let mm=at(r.periods,t),aa=at(subdiv(mm),t),pp=at(subdiv(aa),t),stop=Math.min(pp.end,end);cards.push(`<article class="monthcard"><div class="eyebrow">${fmt(t)} – ${fmt(stop-1)}</div><h3>${lords[mm.i]} / ${lords[aa.i]} / ${lords[pp.i]}</h3><p>Traditional theme: ${themes[lords[pp.i]][0]}. ${themes[lords[pp.i]][1]}</p><p><b>A reflection to try:</b> ${themes[lords[aa.i]][1]}</p></article>`);t=stop}let label=new Date(start).toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'});report=`JYOTISH READING\nBirth UTC: ${new Date(birth).toISOString()}\nLocation: ${$('city').value==='custom'?$('place').value:$('city').selectedOptions[0].text}\nZone: ${z}\nMoon: ${r.moon.toFixed(6)}°\nNakshatra: ${nak[r.n]}\nCurrent: ${lords[m.i]} / ${lords[a.i]} / ${lords[p.i]}\n\n`+visible.map(x=>`${lords[x.i]}: ${fmt(Math.max(birth,x.start))} – ${fmt(x.end)}\n`+subdiv(x).filter(a=>a.end>birth).map(a=>`  ${lords[a.i]}: ${fmt(Math.max(birth,a.start))} – ${fmt(a.end)}`).join('\n')).join('\n')+'\n\n'+'Advanced readings are available in the website; use its Export analysis button.'+'\n\nMethod: Astronomy Engine 2.1.19; approximate Lahiri ayanamsa; 365.25636-day years. Not scientifically validated predictions.'; }catch(err){$('error').textContent=err.message;}};
$('demo').onclick=()=>{$('name').value='Example';$('date').value='1995-06-15';$('time').value='10:30';$('city').selectedIndex=0;$('city').onchange();$('custom').hidden=true;$('offset').value='';$('form').requestSubmit();$('mode').textContent='EXAMPLE CHART'};$('download').onclick=()=>{let url=URL.createObjectURL(new Blob([report],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download='jyotish-reading.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};

$('demo').disabled=false;document.querySelector('button.primary').disabled=false;

$('remember').onchange=()=>{if(!$('remember').checked)try{localStorage.removeItem('jyothish-birth-profile')}catch{}};
try{let saved=JSON.parse(localStorage.getItem('jyothish-birth-profile')||'null');if(saved){$('city').selectedIndex=saved.cityIndex;$('city').onchange();for(let id of ['name','date','time','place','zone','offset','latitude','longitude'])if(saved[id]!==undefined)$(id).value=saved[id];$('remember').checked=true;$('form').requestSubmit();}}catch{}
